@dataclass
class HMTt(HMFormula):
    """Truth."""
    def __repr__(self): return "⊤"

@dataclass
class HMAnd(HMFormula):
    """Conjunction."""
    left: HMFormula
    right: HMFormula
    def __repr__(self): return f"({self.left!r} ∧ {self.right!r})"

@dataclass
class HMNot(HMFormula):
    """Negation."""
    sub: HMFormula
    def __repr__(self): return f"¬{self.sub!r}"

@dataclass
